INSERT INTO `anato_physiology_glosary_items` VALUES (1,'Concepto de prueba','Descripción de prueba','2021-11-19 13:20:55','2021-11-19 13:20:55'),(2,'Otro concepto de prueba','Describo','2021-11-20 01:23:20','2021-11-20 01:23:20'),(3,'Rodilla','rodilla','2021-11-30 13:13:49','2021-11-30 13:36:53'),(4,'Cara','La cara es una estructura ósea aplicada a la parte anteroinferior del cráneo. Sus límites superior e inferior son la frente y el mentón, y los límites laterales son las orejas.','2022-01-07 13:37:21','2022-01-07 13:37:21'),(5,'Abductor','ab, separación del exterior de un límite, separación + ducere, guiar, dirigir.',NULL,NULL),(6,'Acetábulo','acetum, vinagre + abulum, pequeño receptáculo. Pequeña taza de vinagre, cualquier taza pequeña.',NULL,NULL),(7,'Aducción','ad, hacia + ducere, guiar, dirigir.',NULL,NULL),(8,'Ala (alar)','ala, ala.',NULL,NULL),(9,'Alvéolo (alveolar)','alveolus, compartimento pequeño.',NULL,NULL),(10,'Ampolla','ampulla, frasco.',NULL,NULL),(11,'Antecubital','ante, delante, al frente; cubitum, codo.',NULL,NULL),(12,'Anular','anus, anillo.',NULL,NULL),(13,'Apéndice','ad, hacia; pendere, colgar. De ahí apéndice.',NULL,NULL),(14,'Aréola','areola, área pequeña.',NULL,NULL),(15,'Arqueado/a','arcus, arco.',NULL,NULL),(16,'Asa','ansa, asa, mango.',NULL,NULL),(17,'Atrio','atrium, tribunal o sala.',NULL,NULL),(18,'Aurícula','auricula, diminutivo de auris, oreja.',NULL,NULL),(19,'Axila','axilla, axila.',NULL,NULL),(20,'Acromion','acron, cima, cumbre + omos, hombro.',NULL,NULL),(21,'Ancóneo','ancone, codo.',NULL,NULL),(22,'Aponeurosis','apo, a partir de; neur-, tendón. (Los primeros anatomistas griegos  utilizaron el término neurona de forma indiscriminada tanto para  nervios como para tendones).',NULL,NULL),(23,'Aracnoide','arachne, araña; como la tela de una araña.',NULL,NULL),(24,'Aritenoides','arytain-, cazo; los dos cartílagos, con el hueco entre los dos, tienen la forma del pico de un cazo.',NULL,NULL),(25,'Atlas','Atlas, figura mítica; el atlas so