CREATE TABLE `bibliographies` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `drive_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
