INSERT INTO `home_physiotherapy_programs` VALUES (1,'Nuwvo','{\"home_physiotherapy_program_exercises\":[{\"description\":\"vvcn\",\"series\":\"cvnvcn\",\"reps\":\"cvncn\"}]}',1,'2020-12-18 18:00:36','2020-12-18 18:49:41','2020-12-18 18:49:41',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(2,'Rehabilitación de codo','{\"images\":null,\"image\":null,\"home_physiotherapy_program_exercises\":[{\"description\":\"Flexi\\u00f3n de codo\",\"series\":\"4\",\"reps\":\"15\"}],\"home_physiotherapy_program_masajes\":[{\"name\":\"Rejalante\"}],\"home_physiotherapy_program_meds\":[{\"name\":\"Naproxeno\",\"indications\":\"Si tiene dolor\",\"precautions\":\"si tiene enfermedad renal\"}]}',1,'2020-12-18 18:51:05','2022-09-10 10:06:15','2022-09-10 10:06:15',3,NULL,NULL,NULL,NULL,NULL,NULL,0),(3,'Rehabilitación de mano','{\"_token\":\"x2bKDoDdLk7c7oGaXJ16GGlpcYh8PEx5SrpYEKUa\",\"home_physiotherapy_program_exercises\":[{\"description\":\"Flexion-extensi\\u00f3n\",\"series\":\"3\",\"reps\":\"15\"}]}',1,'2020-12-22 18:53:28','2022-09-10 10:06:26','2022-09-10 10:06:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(4,'Bursa trocanterica inflamada','{\"home_physiotherapy_program_exercises\":[{\"description\":null,\"series\":null,\"reps\":null},{\"description\":\"abduccion de cadera acostado de lado se coloca una liga de resistencia y se eleva la pierna\",\"series\":\"5\",\"reps\":\"10\"},{\"description\":\"puente de g\\u00f1uteo- se focaliza en el gluteo mayor, aqui nos acostamos y elevamos la pelvis\",\"series\":\"4\",\"reps\":\"14\"},{\"description\":\"patada de burro, elevamos la pierna y enfatizamos la contracci\\u00f3n del gl\\u00fateo, aqu\\u00ed trabajaremos la pierna derecha e izquierda\",\"series\":\"4\",\"reps\":\"10\"},{\"description\":\"Elevacion de pierna , al igual que la patada de burro nos acomodamos en 4 puntos y ahora hacemos una elevaci\\u00f3n de pierna estirada completamente\",\"series\":\"4\",\"reps\":\"10\"},{\"description\":\"Elevaci\\u00f3n de pierna lateral, aqu\\u00ed nos acostamos  de lado y hacemos elevaci\\u00f3n de pierna de  lado derecho e izquierdo\",\"series\":\"5\",\"reps\":\"8\"},{\"description\":\"estiramiento em rosquilla (Rotaci\\u00f3n de columna) nos colocamos boca arriba y flexionamos la pierna derecha, coloco la planta del pie sobre el suelo y hago una peque\\u00f1a inclinacion del tronco (hacer lado derecho e izuiqerdo)\",\"series\":null,\"reps\":\"15 segundos\"},{\"description\":\"Estiramiento flexi\\u00f3n de rodilla al pecho, nos colocamos boca abajo y flexionamos la rodilla y la llevamos hacis nuestro pecho (pierna izquierda y derecha)\",\"series\":null,\"reps\":\"15 segundos\"},{\"description\":\"Estiramiento flexi\\u00f3n de rodilla al pecho, nos colocamos boca abajo y flexionamos la rodilla y la llevamos hacis nuestro pecho (pierna izquierda y derecha)\",\"series\":null,\"reps\":\"15 segundos\"},{\"description\":\"Estiramiento de cadera y columna sentado, en posici\\u00f3n sentado vamos a flexionar la rodilla y vamos a cruzarla sobre la pierna estirada, despu\\u00e9s de esto vamos a rodear la pierna flexionada con el brazo contrario, de modo que puedas ejercer presi\\u00f3n sobre la pierna para ejercer flexi\\u00f3n en el tronco\",\"series\":null,\"reps\":\"15 segundos\"},{\"description\":\"Estiramiento del musculo piriforme nos colocamos boca arriba coloca el tobillo de la pierna derecha sobre la rodilla de la izquierda y agarramos el muslo izquierdo con llas dos piernas y lo llevamos hacia nosotros y ahora hacemo lo mismo pero del otro lado\",\"series\":null,\"reps\":\"15 segundos\"}],\"home_physiotherapy_program_afs\":[{\"name\":\"contrastes\",\"indications\":\"3 min calor, 3 min frio. 3 min calor, 3 min frio,3 min calor\",\"precautions\":\"cuidar quemaduras, envolver con una toalla para evitar el contacto directo\"}]}',28,'2020-12-28 19:38:50','2022-09-10 10:06:43','2022-09-10 10:06:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(5,'tendinitis del glúteo','{\"home_physiotherapy_program_exercises\":[{\"description\":\"Estiramiento del musculo piriforme nos colocamos boca arriba coloca el tobillo de la pierna derecha sobre la rodilla de la izquierda y agarramos el muslo izquierdo con llas dos piernas y lo llevamos hacia nosotros y ahora hacemo lo mismo pero del otro lado\",\"series\":null,\"reps\":\"15 segundos\"},{\"description\":\"patada de burro, elevamos la pierna y enfatizamos la contracci\\u00f3n del gl\\u00fateo, aqu\\u00ed trabajaremos la pierna derecha e izquierda\",\"series\":\"4\",\"reps\":\"10\"},{\"description\":\"abduccion de cadera acostado de lado se coloca una liga de resistencia y se eleva la pierna\",\"series\":\"4\",\"reps\":\"10\"},{\"description\":\"puente de gl\\u00fateo- se focaliza en el gl\\u00fateo mayor, aqu\\u00ed nos acostamos y elevamos la pelvis\",\"series\":\"4\",\"reps\":\"15\"},{\"description\":\"puente de gl\\u00fateo- se focaliza en el gl\\u00fateo mayor, aqu\\u00ed nos acostamos y elevamos la pelvis\",\"series\":\"4\",\"reps\":\"15\"}]}',28,'2020-12-29 17:53:50','2022-09-10 10:06:58','2022-09-10 10:06:58',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(6,'esguince de tobillo','{\"home_physiotherapy_program_exercises\":[{\"description\":\"Elevaci\\u00f3n de pantorrillas con mancuernas, despega lentamente los talones del suelo manteniendo el equilibrio sobre los metatarsos\",\"series\":\"4\",\"reps\":\"10\"},{\"description\":\"ejercicios con liga de resistencia de los 4 rangos de movimientos del tobillo\",\"series\":\"4\",\"reps\":\"18\"},{\"description\":\"Ejercicio de propiocepci\\u00f3n a un pie   bajar y subir, de la  pierna derecha e izquierda\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"elevacion de pantorrilla a una pierna con tu propio peso, de la pierna derecha e izquierda\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"estiramiento de tobillo de los 4 rangos de movimiento\",\"series\":null,\"reps\":\"10  segundos\"}],\"home_physiotherapy_program_afs\":[{\"name\":\"contrastes\",\"indications\":\"3 min calor, 3 min frio. 3 min calor, 3 min frio,3 min calor\",\"precautions\":\"cuidar quemaduras, envolver con una toalla para evitar el contacto directo\"}]}',28,'2020-12-29 19:32:54','2022-09-10 10:07:10','2022-09-10 10:07:10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(7,'bursitis de codo','{\"home_physiotherapy_program_exercises\":[{\"description\":\"Press de hombro con ligas- apoyamos nuetro pie en la liga de resistencia con los brazos agarramos cada extremo  y  hacemos elevaciones por arriba de la cabeza\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"flexiones en el suelo- en posici\\u00f3n de plancha a la altura de los hombros empiezas a hacer una flexion de codos y bajas lentamente antes de tocar el suelo y vuelves a extender los brazos, esto para trabajar los m\\u00fasculos  triceps y pectorales\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"flexiones con un mano sobre un escal\\u00f3n- posici\\u00f3n en plancha y una mano sobre un caj\\u00f3n haremos una flexion  lentamente hacia abajo antes de llegar al suelo\",\"series\":\"4\",\"reps\":\"8\"},{\"description\":\"Rotaci\\u00f3n lateral del brazo con banda el\\u00e1stica-Sujeta y aprieta un extremo de la banda alrededor de algo que sirva de poste, a la altura del codo, separa el antebrazo lateralmente lo m\\u00e1s lejos que puedas, y posteriormente vuelve a la posici\\u00f3n inicia.\",\"series\":\"3\",\"reps\":\"15\"},{\"description\":\"Elevaciones laterales-sobre una banda el\\u00e1stica , con los brazos a los lados del cuerpo y los pies separados  a la anchura de las caderas, agarra cada extremo de la liga con cada mano y hacemos una elevacion\",\"series\":\"4\",\"reps\":\"10\"},{\"description\":\"Curl de biceps-Con  los codos pegados a los costados, flexiona los brazos y lleva las palmas de las manos hacia el pecho. aqu\\u00ed puedes utilizar alguna mancuerna o liga de resistencia\",\"series\":\"5\",\"reps\":\"12\"},{\"description\":\"Estiramiento de hombro- el brazo derecho cruzando el cuerpo, a la altura del pecho. Con la mano izquierda, aplica presi\\u00f3n contra el codo del brazo derecho.\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"Estiramiento de hombro- el brazo derecho cruzando el cuerpo, a la altura del pecho. Con la mano izquierda, aplica presi\\u00f3n contra el codo del brazo derecho.\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"Estiramiento de hombro- el brazo derecho cruzando el cuerpo, a la altura del pecho. Con la mano izquierda, aplica presi\\u00f3n contra el codo del brazo derecho.\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"Estiramiento de triceps- Levanto  el brazo derecho y flexi\\u00f3nalo por detr\\u00e1s de la cabeza y con la otra mano tiramos del codo suavemente\",\"series\":null,\"reps\":\"10  segundos\"}],\"home_physiotherapy_program_afs\":[{\"name\":\"contrastes\",\"indications\":\"3 min calor, 3 min frio. 3 min calor, 3 min frio,3 min calor\",\"precautions\":\"cuidar quemaduras, envolver con una toalla para evitar el contacto directo\"}]}',28,'2021-01-11 16:49:12','2022-09-10 10:07:26','2022-09-10 10:07:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(8,'Lumbalgias','[]',28,'2021-01-11 18:08:34','2022-09-10 10:08:01','2022-09-10 10:08:01',1,NULL,NULL,NULL,NULL,NULL,NULL,0),(9,'artrosis de cadera','{\"_token\":\"MXCHtm89S0ghC62V719GWXlwh8DytYeXO1uKiSQc\",\"home_physiotherapy_program_exercises\":[{\"description\":\"elevaciones laterales de cadera- acostada, de un lado haremos una elevaciones de cadera trabajando los abductores, de la pierna derecha e izquierda\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"Puente de gl\\u00fateo- se focaliza en el gl\\u00fateo mayor, aqu\\u00ed nos acostamos y elevamos la pelvis\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"abduccion con liga de resistencia- sentado en una silla nos colocamos la liga ligeramente arriba de las rodillas, donde por siguiente abriremos y cerraremos las piernas\",\"series\":\"5\",\"reps\":\"10\"},{\"description\":\"Estiramiento del musculo piriforme nos colocamos boca arriba coloca el tobillo de la pierna derecha sobre la rodilla de la izquierda y agarramos el muslo izquierdo con llas dos piernas y lo llevamos hacia nosotros y ahora hacemo lo mismo pero del otro lado\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"puente de gluteo a una pierna- nos acostamos y elevamos la pelvis pero solo con una pierna, hacemos con la pierna derecha e izquierda\",\"series\":\"4\",\"reps\":\"10\"},{\"description\":\"estiramiento al estilo gato- Arquea la columna a la vez que encoges el vientre, las caderas levantadas y los hombros inm\\u00f3viles.\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"Flexion de rodillas al pecho- nos acostamos boca arriba y flexionamos una rodilla lo mas que podamos a nuestro pecho, derecho e izquierdo.\",\"series\":null,\"reps\":\"10  segundos\"}]}',28,'2021-01-11 18:44:09','2022-09-10 10:08:47','2022-09-10 10:08:47',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(10,'Dorsalgia','{\"_token\":\"MXCHtm89S0ghC62V719GWXlwh8DytYeXO1uKiSQc\",\"home_physiotherapy_program_exercises\":[{\"description\":\"Estiramiento de ni\\u00f1o- ponte de rodillas sobre una superficie c\\u00f3moda, desplaza el cuerpo hacia atr\\u00e1s para sentarte, y deja reposar los gl\\u00fateos sobre los talones, separa las rodillas aproximadamente a la anchura de los hombros y sostenemos esta posicion durante unos segundos\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"Estiramiento de los dorsales con fitball- Nos colocamos de rodillas enfrente de la pelota, elevamos un brazo en la pelota y nuestro cuerpo hacemos hacia atras, del brazo derecho e izquierdo.\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"Estiramiento del dorsal ancho- enlaza las manos por encima de la cabeza y alejamos las manos del cuerpo mientras haces un movimiento circular con el tronco.\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"Remo con ligas- colocamos las ligas a la altura de nuestros hombros, hacemos flexi\\u00f3n  y extensi\\u00f3n del codo\",\"series\":\"4\",\"reps\":\"14\"},{\"description\":\"Remo con una mano-  nos colocamos inclinados, subimos y flexionamos codo, podemos utilizar ligas o alg\\u00fan peso extra.\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"Dominadas- Nos colocamos en las barras paralelas e iniciamos subiendo y bajando  con la fuerza de los brazos , es importante destacar el acomodo de los brazos ya que es el musculo que se trabajara, aqu\\u00ed los brazos estar\\u00e1n abiertos\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"P\\u00e1jaros vuelos invertidos- nos posicionamos en el fitball acostados y levantamos los codos justo hasta sobrepasar la altura de los hombros, con los brazos en la misma posici\\u00f3n.\",\"series\":\"4\",\"reps\":\"12\"}]}',28,'2021-01-11 19:15:30','2022-09-10 10:08:54','2022-09-10 10:08:54',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(11,'contractura del piriforme','{\"images\":null,\"image\":null,\"home_physiotherapy_program_exercises\":[{\"description\":\"puente de gl\\u00fateo- se focaliza en el gl\\u00fateo mayor, aqu\\u00ed nos acostamos y elevamos la pelvis\",\"series\":\"4\",\"reps\":\"15\"},{\"description\":\"abducci\\u00f3n de cadera acostado de lado se coloca una liga de resistencia y se eleva la pierna\",\"series\":\"4\",\"reps\":\"10\"},{\"description\":\"Estiramiento del musculo piriforme nos colocamos boca arriba coloca el tobillo de la pierna derecha sobre la rodilla de la izquierda y agarramos el muslo izquierdo con llas dos piernas y lo llevamos hacia nosotros y ahora hacemo lo mismo pero del otro lado\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"Estiramiento del musculo piriforme nos colocamos boca arriba coloca el tobillo de la pierna derecha sobre la rodilla de la izquierda y agarramos el muslo izquierdo con llas dos piernas y lo llevamos hacia nosotros y ahora hacemo lo mismo pero del otro lado\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"patada de burro, elevamos la pierna y enfatizamos la contracci\\u00f3n del gl\\u00fateo, aqu\\u00ed trabajaremos la pierna derecha e izquierda\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"hip thrust- Nos colocamos en una posici\\u00f3n c\\u00f3moda un poco arriba de los omoplatos y con las piernas bien colocadas hacemos una retroversi\\u00f3n p\\u00e9lvica subiendo y bajando, haciendo tensi\\u00f3n en el gl\\u00fateo mayor.\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"Frog glute bridge-  nos acostamos y acomodamos las piernas en forma inclinada como de rana y hacemos una elevaci\\u00f3n p\\u00e9lvica\",\"series\":\"4\",\"reps\":\"12\"}]}',28,'2021-01-11 19:31:50','2022-09-10 10:09:01','2022-09-10 10:09:01',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(12,'hernia lumbar posterior','{\"home_physiotherapy_program_exercises\":[{\"description\":\"puente de gl\\u00fateo- se focaliza en el gl\\u00fateo mayor, aqu\\u00ed nos acostamos y elevamos la pelvis\",\"series\":null,\"reps\":null},{\"description\":\"Estiramiento del musculo piriforme nos colocamos boca arriba coloca el tobillo de la pierna derecha sobre la rodilla de la izquierda y agarramos el muslo izquierdo con llas dos piernas y lo llevamos hacia nosotros y ahora hacemo lo mismo pero del otro lado\",\"series\":null,\"reps\":\"10  segundos\"},{\"description\":\"frog pumps- este ejercicio consiste en colocarnos en el suelo boca arriba y con las piernas dobladas un poco inclinadas a 45 grados hacer una elevacion de la pelvis.\",\"series\":\"4\",\"reps\":\"12\"},{\"description\":\"Estiramiento Cat Cow - consiste en colocarnos en el suelo en 4 puntos y haremos una elevacion de la espalda metiendo la cabeza y despues en la misma posicion meteremos la espalda lo mas que podamos y voltearemos hacia al frente\",\"series\":null,\"reps\":\"12-12 segundos\"},{\"description\":\"estiramiento rodilla al pecho- nos colocamos boca arriba y vamos a llevar una de nuestras rodillas a nuestro pecho por tiempo y despues la otra\",\"series\":null,\"reps\":\"12-12 segundos\"},{\"description\":\"Estiramiento del musculo piriforme nos colocamos boca arriba coloca el tobillo de la pierna derecha sobre la rodilla de la izquierda y agarramos el muslo izquierdo con llas dos piernas y lo llevamos hacia nosotros y ahora hacemo lo mismo pero del otro lado\",\"series\":null,\"reps\":\"12-12 segundos\"},{\"description\":\"remo con liga- nos colocamos parados un poco inclinada la espalda pero recta y pisando nuestra liga haremos una extencion y flexion de nuestro brazo enfoc\\u00e1ndonos en el m\\u00fasculos de la espalda alta\",\"series\":\"4\",\"reps\":\"12-12 segundos\"},{\"description\":\"remo con liga- nos colocamos parados un poco inclinada la espalda pero recta y pisando nuestra liga haremos una extencion y flexion de nuestro brazo enfoc\\u00e1ndonos en el m\\u00fasculos de la espalda alta\",\"series\":\"4\",\"reps\":\"12\"}]}',28,'2021-01-18 17:35:05','2022-09-10 10:09:10','2022-09-10 10:09:10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(13,'Contractura de la fascia lata','{\"images\":null,\"image\":null,\"home_physiotherapy_program_exercises\":[{\"description\":\"Estiramiento del musculo piriforme nos colocamos boca arriba coloca el tobillo de la pierna derecha sobre la rodilla de la izquierda y agarramos el muslo izquierdo con llas dos piernas y lo llevamos hacia nosotros y ahora hacemo lo mismo pero del otro lado\",\"series\":null,\"reps\":null},{\"description\":\"Elevaciones laterales- nos colocamos acostados de lado y vamos a iniciar con elevaciones laterales de pierna  de cada una\",\"series\":\"4\",\"reps\":\"15\"},{\"description\":\"Elevaciones laterales- nos colocamos acostados de lado y vamos a iniciar con elevaciones laterales de pierna  de cada una\",\"series\":\"4\",\"reps\":\"15\"},{\"description\":\"estiramiento pie cruzado- nos sentamos en el suelo y vamos a cruzar nuestro pie hacia un extremo y nuestra otra pierna estirada, lo qe haremos es con el brazo contrario jalar levemente la pierna cruzada y asi el otro lado\",\"series\":null,\"reps\":\"10-10 segundos\"},{\"description\":\"elevaciones laterales con polaina- nos colocamos las polainas en los tobillos y nos acostamos de lado y vamos a iniciar con elevaciones laterales de un pie y luego cambiamos de lado\",\"series\":\"4\",\"reps\":\"10\"},{\"description\":\"Elevaciones laterales con ligas de resistencia- nos colocamos la liga un poco arriba de las rodillas y nos acostamos de lado y vamos a iniciar con elevacion de una pierna y despues el siguiente\",\"series\":\"4\",\"reps\":\"10\"}]}',28,'2021-01-21 18:27:08','2022-09-10 10:09:18','2022-09-10 10:09:18',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(14,'post operación del túnel del copey','{\"_token\":\"pMAxbBEtA6cgIiTCkxEkPnTfvLUpi9HcrNaDXjCj\"}',28,'2021-01-26 13:19:50','2022-09-10 10:09:28','2022-09-10 10:09:28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(15,'HFEC Prueba','',1,'2021-02-04 14:41:45','2022-09-10 10:13:43','2022-09-10 10:13:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(16,'post operacion de menisco','',1,'2021-02-09 17:29:20','2022-09-10 10:13:56','2022-09-10 10:13:56',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(17,'Tendinitis del psoas','',1,'2021-07-14 16:16:29','2021-07-14 16:27:09','2021-07-14 16:27:09',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(18,'tendinitis de psoas','',1,'2021-07-14 16:27:41','2021-07-14 16:40:02','2021-07-14 16:40:02',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(19,'Fascitis Plantar','',1,'2021-07-29 17:05:11','2021-08-04 17:15:40','2021-08-04 17:15:40',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(20,'Fascitis Plantar','',1,'2021-07-29 17:16:33','2021-08-04 17:15:43','2021-08-04 17:15:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(21,'Programa de prueba, DR Luis Ruelas','',1,'2021-08-04 13:33:46','2022-09-10 10:14:10','2022-09-10 10:14:10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0),(22,'Fascitis Plantar','',1,'2021-08-04 17:28:50','2022-02-18 12:48:56','2022-02-18 12:48:56',NULL,NULL,NULL,NULL,NULL,NULL,