INSERT INTO `hpp_physical_agent` VALUES (1,4,'3 min calor, 3 min frio. 3 min calor, 3 min frio, 3 min calor','cuidar quemaduras, envolver con una toalla para evitar el contacto directo',NULL,NULL),(2,6,'3 min calor, 3 min frio. 3 min calor, 3 min frio,3 min calor','cuidar quemaduras, envolver con una toalla para evitar el contacto directo',NULL,NULL),(3,7,'3 min calor, 3 min frio. 3 min calor, 3 min frio,3 min calor','cuidar quemaduras, envolver con una toalla para evitar el contacto directo',NULL,NULL),(4,15,'indico','precavo',NULL,NULL),(5,17,'10 minutos despues de terminar los ejercicios.',NULL,NULL,NULL),(6,18,'colocar hielo durante 10 min después del ejercicio',NULL,NULL,NULL),(8,21,'físico','2',NULL,NULL),(9,22,'solo colocarse el hielo, cuando duela o cuando termine de hacer los ejercicios.','no dejar mas tiempo de lo indicado porque puede quemar o lastimar',NULL,NULL),(10,32,'a.	Disminuye la inflamación, el dolor y el tiempo de recuperación. b.	Aplicar 10 minutos cada 8 horas. c.	También puede aplicar calor y frío sería un contraste, si empieza con calor terminar con calor aplicar unos 10 minutos,(el calor puedo aplicarlo con un calcetín lleno de arroz y colocarlo en el horno de microondas o una toalla húmedo-caliente).','no dejar mas tiempo porque puedes irritar la ´piel o quemarla',NULL,NULL),(11,42,'Durante 10 minutos después de su actividades o después de realizar sus ejercicios en casa','no dejar demasiado tiempo porque puede quemar',NULL,NULL),(12,42,'Durante 10 minutos antes de su actividades o antes de realizar sus ejercicios en casa para que caliente mas fácil el musculo y desinflame','no dejar demasiado tiempo porque puede quemar',NULL,NULL),(13,43,'a. Disminuye la inflamación, el dolor y el tiempo de recuperación.  b. Aplicar 10 minutos cada 8 horas.  c.También puede aplicar calor y frío sería un contraste, si empieza con calor terminar con calor aplicar unos 10 minutos,(el calor puedo aplicarlo con un calcetín lleno de arroz y colocarlo en el horno de microondas o una toalla húmedo-caliente).','no dejar mas porque puede quemar',NULL,NULL),(14,44,'Colocarse un compresa caliente en la zona cuando se sienta con dolor o en tensión ayudara a relajar','no poner mas de 30 minutos porque puede quemar',NULL,NULL),(15,44,'Colocarse un compresa fría en la zona cuando se sienta con dolor o este inflamado ayudara a disminuir el dolor y la inflamación  solo por 20 minutos','no poner mas de lo que no esta indicado',NULL,NULL),(16,45,'a)	Colocar 20 minutos hielo en la planta del pie. b)	Puede hacerse con un ejercicio de congela una botella de agua y utilizarla como rodilla.','no colocar mas del tiempo asignado',NULL,NULL),(17,46,'colocar un compresa caliente durante 15 minutos','no colocar mas de lo que no esta indicado, porque puede quemar',NULL,NULL),(18,46,'colocar un compresa fría durante 20 minutos','no colocar mas de lo que no esta indicado, porque puede quemar',NULL,NULL),(19,47,': colocarse 20 min una compresa fría para desinflamar la zona','no durar mas del tiempo que se le indica',NULL,NULL),(20,48,'colocarte 10 minutos cuando tengas un poco de dolor o rigidez.','no colocar mas tiempo de lo indicado',NULL,NULL),(21,48,'colocarte 20 minutos después de realizar actividad física para desinflamar y relajar.','no colocar mas tiempo de lo indicado',NULL,NULL),(22,49,'colocar 20 minutos','no colocar mas de lo indicado porque puede a ver quemaduras',NULL,NULL),(23,50,'la zona donde esta lesión durante unos 20 minutos.',NULL,NULL,NULL),(24,59,'colocar 10 minutos en la zona','no colocar mas de 20 minutos en la zona',NULL,NULL),(25,59,'colocar 20 minutos en la zona',NULL,NULL,NULL),(26,62,'Colocar 10 minutos en la zona afectada','no poner mas de 20 minutos en la zona',NULL,NULL),(27,61,'colocar 10 minutos en cada zona','no pasar mas de 10 minuto porque pueden lastimar',NULL,NULL),(28,63,'colocar solamente 10 minutos en la zona','no colocar mas de lo esta indicado',NULL,NULL),(29,64,'colocar solamente 10 minutos en la zona afectada','no poner mas de los 10 minutos',NULL,NULL),(30,64,'colocar solamente 10 minutos en la zona afectada','no poner mas de los 10 minutos',NULL,NULL),(31,65,'Colocar en la zona si se inflama el tobillo o la cicatriz, Unos 10-20 minutos.','no colocar mas de lo que esta indicado',NULL,NULL),(32,65,'Si le molesta el hielo, puede utilizar contrastes de calor y frio, si coloca primero hielo terminar con hielo, si comienza con calor terminar calor. Unos 10-20 minutos','no colocar mas de lo que esta indicado',NULL,NULL),(33,66,'colocar en zona afectada 10 minutos','no colocar mas de 20 minutos',NULL,NULL),(34,66,'colocar en zona afectada 10 minutos','no colocar mas de 20 minutos',NULL,NULL),(35,67,'colocarse de 10 min a 15 min en la zona de dolor','no colocar mas de lo que no esta indicado',NULL,NULL),(36,68,'colocarse unos 20 minutos para desinflame la zona','solo colocar lo que esta indicado',NULL,NULL),(37,68,'colocarse unos 20 minutos para desinflame la zona','solo colocar lo que esta indicado',NULL,NULL),(38,69,'colocar solo 10 minutos en la zona afectada','no colocar mas de lo que esta indicado',NULL,NULL),(39,69,'colocar solo 10 minutos en la zona afectada','no colocar mas de lo que esta indicado',NULL,NULL),(40,70,'colocar 10 minutos en la zona afectada','no colocar mas de los 10 minutos',NULL,NULL),(41,70,'colocar 10 minutos en la zona afectada','no colocar mas de los 10 minutos',NULL,NULL),(42,71,'colocar 10 minutos en la zona afectada','solo colocar lo que esta indicado',NULL,NULL),(43,72,'colocar 10 minutos en la zona donde duele','solo colocar los 10 minutos que esta indicado',NULL,NULL),(44,73,'colocar 10 minutos en la zona afectada','no poner mas de lo que esta indicado y de igual forma sino duele al tener los 10 minutos disminuirlo a 5',NULL,NULL),(45,74,'colocar solo 10 minutos en la zona afectada','no colocar mas de lo indicado',NULL,NULL),(46,75,'colocar 10 minutos en zona afectada','no colocar mas de lo indicado',NULL,NULL),(47,75,'colocar 10 minutos en zona afectada','no colocar mas de lo indicado',NULL,NULL),(48,76,'colocar 10 minutos en la zona','no colocar mas de 10 min',NULL,NULL),(49,78,'Colocarlo 10 minutos en la zona lumbar, para relajar  los músculos contrarios',NULL,NULL,NULL),(53,78,'10 minutos','Evitar en caso de dolor',NULL,NULL),(54,79,'15 minutos','si esta muy caliente poner una toalla debajo de la compresa',NULL,NULL),(55,80,'10  minutos en la zona afectada',NULL,NULL,NULL),(56,81,'15 minutos en la zona afectada',NULL,NULL,NULL),(57,83,'10 minutos en la zona afectada',NULL,NULL,NULL),(58,85,'colocar 10 minutos en la zona afectada después de realizar el ejercicio B)	En caso de dolor','si esta muy frio colocar una tela debajo del hielo',NULL,NULL),(59,86,'Colocar  10 minutos en la zona afectada en caso de dolor, después de terminar los ejercicios B)	En caso de dolor',NULL,NULL,NULL),(60,87,'15 minutos  en la zona afectada en caso de dolor y al terminar de realizar los ejercicios. B)	En caso de dolor',NULL,NULL,NULL),(61,88,'15 minutos en la zona afectada. B)	 En caso de dolor  C)	Al terminar los ejercicios si siente dolor',NULL,NULL,NULL),(62,90,'15 minutos en la zona afectada    En caso de dolor  	Al terminar los ejercicios si siente dolor',NULL,NULL,NULL),(63,91,'10 minutos en la zona, para relajar b)	En caso de dolor  c)	Después de realizar los ejercicios si hay dolor',NULL,NULL,NULL),(64,92,'por unos 10 minutos  en la zona del dolor después de hacer los ejercicios •	En caso de dolor','•	Colocar una toalla debajo de la compresa por que puede llegar a quemar',NULL,NULL),(65,93,'durante unos 10 minutos antes de empezar sus ejercicios.  al final de tus ejercicios durante unos 10 minutos para desinflamar.',NULL,NULL,NULL),(66,94,'10 minutos en cada zona que se lesiono',', no poner más de 20 minutos.',NULL,NULL),(67,95,'colocar 15 minutos en caso de dolor o al terminar los ejercicios',NULL,NULL,NULL),(68,96,'colocar en la zona del dolor 10 minutos puede hacer contraste',NULL,NULL,NULL),(69,97,'colocar 1o minutos cada una se puede hacer contraste',NULL,NULL,NULL),(70,98,'por 15 minutos en la zona afectada       B) En caso de dolor       C) Al terminar los ejercicios si siente dolor',NULL,NULL,NULL),(71,99,'en la zona afectada, porque ayuda a la desinflamación y si tiene algún edema disminuye. colocar 10 minutos',NULL,NULL,NULL),(72,100,'Colocar 20 minutos en caso de dolor y al terminar los ejercicios','Colocar una toalla abajo y colocar la compresa fria arriba para que la sienta agusto',NULL,NULL),(73,101,'10 minutos en la zona de dolor para desinflamar, calmar dolor, edema e inflamación',NULL,NULL,NULL),(74,102,'colocar 10 minutos en la zona de  dolor al finalizar de cada ejercicio para que desinflame','si molesta el frío colocar una toalla debajo',NULL,NULL),(75,107,'Ponerla antes de realizar los ejercicios, solo 12 minutos','No dejarla mas del tiempo indicado',NULL,NULL),(76,107,'Dejarla por 12 minutos antes de realizar los ejercicios','No dejarla mas del tiempo indicado',NULL,NULL),(77,108,'Aplicación de frío local: disminuye la inflamación, el dolor y el tiempo de recuperación. .Aplicar 10 minutos cada 8 horas.','Tener cuidado de no dejarlo más del tiempo indicado por que puede ocasionar quemadura.',NULL,NULL),(78,110,'uso de compresa hecha a base de un calcetín o tela delgada rellena de semillas como arroz, ponerla al microondas o una toalla húmeda-caliente para relajación de musculatura.  * Aplicar antes o después del entrenamiento si existe alguna molestia de dolor.','Tener cuidado de no calentar demasiado la compresa para evitar quemadura',NULL,NULL),(79,113,'Aplicación de frío local: 10 minutos después de cada sesión de entrenamiento, para disminución de inflamación, aumento de riego sanguíneo  y disminuir tiempo de recuperación','No aplicar más del tiempo para evitar quemadura',NULL,NULL),(81,116,'Usar la compresa para aumento de irrigación sanguínea desinflamar','Usar solamente por 10 minutos puede ocasionar quemaduras',NULL,NULL),(82,118,'Compresa caliente para vascularización, relajación muscular','poner compresa sobre una toalla para evitar quemar y solo poner durante un tiempo estimado de 10 minutos',NULL,NULL),(83,119,'realizan de la siguiente manera: 1 minuto de frio 2 de calor 1 minuto de frio 2 de calor 1 minuto de frio se inicia con frio y se termina con frio cabe mencionar que es también ayuda si hay algún tipo de inflamación e incluso dolor','tener cuidado con la temperatura',NULL,NULL),(84,119,'se coloca el calor sobre la zona que buscamos relajar','tener cuidado con la temperatura',NULL,NULL),(85,119,'colocar la compresa fría sobre la zona que buscamos tener analgesia','puede llegar a se incomodo si quema retirarlo',NULL,NULL),(86,123,'Colocar una bolsita con hielo envuelta en un trapito y dejarla en la zona de dolor o molestia por 10 min','No dejara mas del tiempo indicado',NULL,NULL),(87,124,'Colocar en la zona de dolor una compresa de hielo, durante 10 minutos.','No colocar más del tiempo indicado y, colocar una toalla para evitar alguna quemadura.',NULL,NULL),(88,125,'Utilizar durante 10 Minutos cubriendo la compresa con una toalla y colocándola sobre la zona afectada para aumento de riego sanguíneo y quitar el dolor','No usar más de 10 minutos para evitar quemadura.',NULL,NULL),(89,126,'Colocar electrodos siguiendo el recorrido nervioso, con una intensidad de 30-50 Hz, con duración de 20 minutos.','Evitar subir más la intensidad de la corriente a lo tolerable del paciente para evitar alguna quemadura con el electrodo.',NULL,NULL),(90,127,'Usar la compresa por 10 minutos para aliviar dolor e inflamación.','Utilizar la compresa a una temperatura tolerable por el paciente  y si siente que le quema envolver en una toalla.',NULL,NULL),(91,128,'Colocar los electrodos en el área afectada y utilizar una intensidad de 10Hz, con una duración de 20 minutos.','No aumentar la intensidad más de lo tolerable por el paciente.',NULL,NULL),(92,129,'Aumento de riego sanguíneo y desinflamatorio','No poner por mas de diez minutos y sin uso de toalla',NULL,NULL),(93,130,'Colocar los electrodos en el área de dolor, con una intensidad de 50Hz, con una duración de 20 minutos.','No aumentar la intensidad de la corriente más de lo que pueda tolerar el paciente.',NULL,NULL),(94,131,'Utilizar electroterapia mientras hace ejercicios de fortalecimiento','No exceder la fuerza empleada y no subir los parámetros indicadoss',NULL,NULL),(95,132,'Colocar los electrodos en la zona de dolor, con una intensidad de 50Hz, durante 20 minutos.','No sobrepasar la tolerancia del paciente a los electrodos para evitar una quemadura.',NULL,NULL),(96,133,'para desinflamar la zona o cuando hay dolor','Colocar una toalla debajo para que no le queme',NULL,NULL),(97,135,'A)15 minutos  en la zona afectada B) en caso de dolor o después de terminar los ejercicios.',NULL,NULL,NULL),(98,136,'15 minutos',NULL,NULL,NULL),(99,137,'Colocar la compresa alrededor de 10 minutos en la zona de dolor usando una toalla junto con la compresa','Tener cuidado con el tiempo  para evitar quemaduras',NULL,NULL),(100,138,'Poner una compresa de hielo en la zona donde haya dolor e inflamación, y dar un pequeño masaje durante 5 u 8 minutos.','Tener cuidado con los tiempo y con no dejar a compresa en un sólo lugar para evitar quemaduras.',NULL,NULL),(101,139,'Usar durante 10 minutos en la zona afectada para relajar y desinflamar zona','Usar en conjunto de una toalla para evitar quemadura',NULL,NULL),(102,140,'Poner una compresa caliente en la zona de dolor, utilizando una toalla para evitar alguna quemadura, con una duración de la menos 10 minutos.','Tener cuidado con el tiempo y temperatura de la compresa para evitar algún tipo de quemadura.',NULL,NULL),(103,141,'Usar durante 10 minutos en conjunto de una toalla','Tener cuidado con no calentar de más para evitar quemadura',NULL,NULL),(104,142,'Poner una compresa caliente, envuelta en una toalla en la zona de dolor durante al menos 10 minutos.','Tener cuidado con al temperatura y los tiempo para evitar algún tipo de quemadura.',NULL,NULL),(105,146,'Colocar CHC durante 15- 20 minutos.','Verificar la temperatura de la CHC para evitar quemaduras.',NULL,NULL),(106,146,'Colocar corriente analgésica en la zona de dolor, durante 15- 20 minutos.','Verificar la intensidad de la corriente.',NULL,NULL),(107,147,'Colocar infrarrojo durante 10 minutos en la rodilla.','Colocar el infrarrojo a una altura adecuada para evitar una quemadura.',NULL,NULL),(108,148,'Colocar CHC en la zona para el aumento del riego sanguíneo.','Verificar la temperatura de la compresa para evitar quemaduras.',NULL,NULL),(109,149,'Colocar ultrasonido durante 10 minutos en la zona de dolor.','NO utilizar en pacientes que tengan placas/prótesis.',NULL,NULL),(110,150,'Colocar una compresa fría en la zona plantar del pie, durante 10 minutos.','Evitar el contacto directo con la compresa.',NULL,NULL),(111,151,'Aplicar CHC en la parte posterior de la pierna durante 15-20 minutos','Evitar el contacto directo con la compresa y verificar que el calor sea el adecuado',NULL,NULL),(112,152,'Al comenzar o terminar los ejercicios se recomienda utilizar una compresa caliente, en caso de no contar con alguna, se puede utilizar una toalla húmeda y calentarla durante dos minutos en el microondas, envolverla sobre una bolsa de plástico y enseguida en otra toalla seca para mantener el calor, posteriormente la colocar en el hombro durante 10 minutos.','Tener cuidado con la te,peratura de la compresa para evitar quemaduras.',NULL,NULL),(113,153,'Dejarlo solamente 10 minutos, aplicarlo antes de iniciar con los ejercicios','No dejarlo mas del tiempo indicado',NULL,NULL),(114,154,'Colocarla antes de realizar los ejercicios para relajar el músculo','Solo dejarla 10 minutos',NULL,NULL),(115,155,'B)	 Colocar una toalla debajo si la siente muy fría.                       En caso de dolor C)	Al terminar los ejercicios si siente dolor',NULL,NULL,NULL);
