DROP TABLE IF EXISTS `hpp_prescription`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hpp_prescription` (
  `prescription_id` bigint unsigned NOT NULL,
  `home_physiotherapy_program_id` bigint unsigned NOT NULL,
  `indication` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `precautions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  KEY `hpp_prescription_prescription_id_foreign` (`prescription_id`),
  KEY `hpp_prescription_home_physiotherapy_program_id_foreign` (`home_physiotherapy_program_id`),
  CONSTRAINT `hpp_prescription_home_physiotherapy_program_id_foreign` FOREIGN KEY (`home_physiotherapy_program_id`) REFERENCES `home_physiotherapy_programs` (`id`),
  CONSTRAINT `hpp_prescription_prescription_id_foreign` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

