--
-- Table structure for table `image_resources`
--

DROP TABLE IF EXISTS `image_resources`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `image_resources` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `terapeutic_plan_id` bigint unsigned DEFAULT NULL,
  `diagnosis_plan_id` bigint unsigned DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `clinic_id` bigint unsigned DEFAULT NULL,
  `exercise_id` bigint unsigned DEFAULT NULL,
  `massage_id` bigint unsigned DEFAULT NULL,
  `physical_agent_id` bigint unsigned DEFAULT NULL,
  `prescription_id` bigint unsigned DEFAULT NULL,
  `laboral_company_id` bigint unsigned DEFAULT NULL,
  `laboral_therapeutic_plan_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `image_resources_diagnosis_plan_id_foreign` (`diagnosis_plan_id`),
  KEY `image_resources_terapeutic_plan_id_foreign` (`terapeutic_plan_id`),
  KEY `image_resources_clinic_id_foreign` (`clinic_id`),
  KEY `image_resources_laboral_company_id_foreign` (`laboral_company_id`),
  KEY `image_resources_laboral_therapeutic_plan_id_foreign` (`laboral_therapeutic_plan_id`),
  CONSTRAINT `image_resources_clinic_id_foreign` FOREIGN KEY (`clinic_id`) REFERENCES `clinics` (`id`),
  CONSTRAINT `image_resources_diagnosis_plan_id_foreign` FOREIGN KEY (`diagnosis_plan_id`) REFERENCES `diagnosis_plans` (`id`) ON DELETE CASCADE,
  CONSTRAINT `image_resources_laboral_company_id_foreign` FOREIGN KEY (`laboral_company_id`) REFERENCES `laboral_companies` (`id`),
  CONSTRAINT `image_resources_laboral_therapeutic_plan_id_foreign` FOREIGN KEY (`laboral_therapeutic_plan_id`) REFERENCES `laboral_therapeutic_plans` (`id`),
  CONSTRAINT `image_resources_terapeutic_plan_id_foreign` FOREIGN KEY (`terapeutic_plan_id`) REFERENCES `terapeutic_plans` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1848 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

