DROP TABLE IF EXISTS `outside_resources`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `outside_resources` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `terapeutic_plan_id` bigint unsigned DEFAULT NULL,
  `diagnosis_plan_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `outside_resources_diagnosis_plan_id_foreign` (`diagnosis_plan_id`),
  KEY `outside_resources_terapeutic_plan_id_foreign` (`terapeutic_plan_id`),
  CONSTRAINT `outside_resources_diagnosis_plan_id_foreign` FOREIGN KEY (`diagnosis_plan_id`) REFERENCES `diagnosis_plans` (`id`) ON DELETE CASCADE,
  CONSTRAINT `outside_resources_terapeutic_plan_id_foreign` FOREIGN KEY (`terapeutic_plan_id`) REFERENCES `terapeutic_plans` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=460 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

