--
-- Table structure for table `sessions`
--

DROP TABLE IF EXISTS `sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `session_objective_id` bigint unsigned NOT NULL,
  `clinical_history_id` bigint unsigned NOT NULL,
  `number_of_session` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `activities` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `observations` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `user_text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `date` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_session_objective_id_foreign` (`session_objective_id`),
  KEY `sessions_user_id_foreign` (`user_id`),
  KEY `sessions_clinical_history_id_foreign` (`clinical_history_id`),
  CONSTRAINT `sessions_clinical_history_id_foreign` FOREIGN KEY (`clinical_history_id`) REFERENCES `clinical_histories` (`id`),
  CONSTRAINT `sessions_session_objective_id_foreign` FOREIGN KEY (`session_objective_id`) REFERENCES `session_objectives` (`id`),
  CONSTRAINT `sessions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1364 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

