--
-- Table structure for table `valorations`
--

DROP TABLE IF EXISTS `valorations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `valorations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `present` tinyint(1) DEFAULT NULL,
  `json_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `section` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cie10_id` bigint unsigned DEFAULT NULL,
  `clinical_history_id` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `valorations_cie10_id_foreign` (`cie10_id`),
  KEY `valorations_clinical_history_id_foreign` (`clinical_history_id`),
  KEY `valorations_user_id_foreign` (`user_id`),
  CONSTRAINT `valorations_cie10_id_foreign` FOREIGN KEY (`cie10_id`) REFERENCES `cat_cie10s` (`id`),
  CONSTRAINT `valorations_clinical_history_id_foreign` FOREIGN KEY (`clinical_history_id`) REFERENCES `clinical_histories` (`id`),
  CONSTRAINT `valorations_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=61233 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

