INSERT INTO `valorations` VALUES (32089,'Objetivo',NULL,'Disminuir el dolor y hacer que la musculatura cicatrice de manera optima','physiotherapy_classic_objective',NULL,261,'2022-09-20 12:42:58','2022-09-20 12:42:58',NULL,48),(32090,'Numero de sesión',NULL,'8','physiotherapy_classic_numero_de_sesion',NULL,261,'2022-09-20 12:42:58','2022-09-20 12:42:58',NULL,48),(32091,'Actividades',NULL,'Premoduladas 80-150Hz, 20 minutos. \r\nUltrasonido 1MHz, 70%, 0.5w, 10 minutos. \r\nMasaje, tracciones, 10 minutos. \r\nEjercicios de fortalecimiento y propiocepción.','physiotherapy_classic_actividades',NULL,261,'2022-09-20 12:42:58','2022-09-20 12:42:58',NULL,48),(32092,'Observaciones',NULL,'El paciente notó una sensación de alivio y mejoría.','physiotherapy_classic_observaciones',NULL,261,'2022-09-20 12:42:58','2022-09-20 12:42:58',NULL,48),(32093,'Fisioterapeuta',NULL,'santiago Emmanuel Corona Valdez.','physiotherapy_classic_fisioterapeuta',NULL,261,'2022-09-20 12:42:58','2022-09-20 12:42:58',NULL,48),(32094,'Objetivo',NULL,'Disminuir el dolor en zona lumbar.','physiotherapy_classic_objective',NULL,314,'2022-09-20 17:29:30','2022-09-20 17:29:30',NULL,41),(32095,'Numero de sesión',NULL,'1','physiotherapy_classic_numero_de_sesion',NULL,314,'2022-09-20 17:29:30','2022-09-20 17:29:30',NULL,41),(32096,'Actividades',NULL,'Se le aplico al paciente la corriente Interferencial tetrapolar durante 20 minutos en la zona lumbar acompañado de la compresa caliente.\r\nEn seguida se le aplico US a un 1Hz por 7 min. al 20%.\r\nDespués realizamos masaje relajante en la zona afectada por 10 minutos. \r\nDespués realizamos ejercicios de fortalecimiento muscular isométricos a cor abdominal y glúteos durante 5 minutos. \r\nTambién realizamos estiramientos paravertebrales lumbares y erectores de columna dando énfasis en el lado derecho.\r\nPor ultimo realizamos el ejercicio de gato camello ya que este ejercicio esta destinado para la zona lumbar, con la finalidad de dar mayor flexibilidad, movilidad y fuerza.\r\nTambién realizamos los ejercicios de William que nos ayudaran en la zona lumbar para fortalecimiento de abdominales y estiramiento de la fascia lumbar, cada ejercicio lo realizamos 3 series de 10.\r\nEl primer ejercicio el paciente se pone en posición de decúbito supino con las caderas y rodillas flexionadas con los pies sobre la camilla, se le pide que presione la zona lumbar sobre la camilla.\r\nEl segundo ejercicio igual la misma posición decúbito supino pero ahora se le pide que leve una rodilla hacia el pecho y que mantenga y después relaje y lo realice con la otra pierna alternando.\r\nEl tercer ejercicio igual la misma posición de decúbito supino pero ahora se le pide que lleve las 2 rodillas al pecho sosteniéndolas con sus manos unos segundos y después soltarlas.','physiotherapy_classic_actividades',NULL,314,'2022-09-20 17:29:30','2022-09-20 17:29:30',NULL,41),(32097,'Observaciones',NULL,'El paciente presenta dolor en la zona lumbar.','physiotherapy_classic_observaciones',NULL,314,'2022-09-20 17:29:30','2022-09-20 17:29:30',NULL,41),(32098,'Fisioterapeuta',NULL,'Lic. Antonio Mendoza','physiotherapy_classic_fisioterapeuta',NULL,314,'2022-09-20 17:29:30','2022-09-20 17:29:30',NULL,41),(32099,'Objetivo',NULL,'Disminuir el dolor en zona lumbar.','physiotherapy_classic_objective',NULL,314,'2022-09-20 17:31:36','2022-09-20 17:31:36',NULL,41),(32100,'Numero de sesión',NULL,'2','physiotherapy_classic_numero_de_sesion',NULL,314,'2022-09-20 17:31:36','2022-09-20 17:31:36',NULL,41),(32101,'Actividades',NULL,'Se le aplico al paciente la corriente Interferencial tetrapolar durante 20 minutos en la zona lumbar acompañado de la compresa caliente. En seguida se le aplico US a un 1Hz por 7 min. al 20%. Después realizamos masaje relajante en la zona afectada por 10 minutos. Después realizamos ejercicios de fortalecimiento muscular isométricos a cor abdominal y glúteos durante 5 minutos. También realizamos estiramientos paravertebrales lumbares y erectores de columna dando énfasis en el lado derecho. Por ultimo realizamos el ejercicio de gato camello ya que este ejercicio esta destinado para la zona lumbar, con la finalidad de dar mayor flexibilidad, movilidad y fuerza. También realizamos los ejercicios de William que nos ayudaran en la zona lumbar para fortalecimiento de abdominales y estiramiento de la fascia lumbar, cada ejercicio lo realizamos 3 series de 10. El primer ejercicio el paciente se pone en posición de decúbito supino con las caderas y rodillas flexionadas con los pies sobre la camilla, se le pide que presione la zona lumbar sobre la camilla. El segundo ejercicio igual la misma posición decúbito supino pero ahora se le pide que leve una rodilla hacia el pecho y que mantenga y después relaje y lo realice con la otra pierna alternando. El tercer ejercicio igual la misma posición de decúbito supino pero ahora se le pide que lleve las 2 rodillas al pecho sosteniéndolas con sus manos unos segundos y después soltarlas.','physiotherapy_classic_actividades',NULL,314,'2022-09-20 17:31:36','2022-09-20 17:31:36',NULL,41),(32102,'Observaciones',NULL,'El paciente presenta dolor en la zona lumbar.','physiotherapy_classic_observaciones',NULL,314,'2022-09-20 17:31:36','2022-09-20 17:31:36',NULL,41),(32103,'Fisioterapeuta',NULL,'Lic. Antonio Mendoza.','physiotherapy_classic_fisioterapeuta',NULL,314,'2022-09-20 17:31:36','2022-09-20 17:31:36',NULL,41),(32104,'Objetivo',NULL,'Disminuir el dolor en zona lumbar.','physiotherapy_classic_objective',NULL,314,'2022-09-20 17:32:34','2022-09-20 17:32:34',NULL,41),(32105,'Numero de sesión',NULL,'3','physiotherapy_classic_numero_de_sesion',NULL,314,'2022-09-20 17:32:34','2022-09-20 17:32:34',NULL,41),(32106,'Actividades',NULL,'Se le aplico al paciente la corriente Interferencial tetrapolar durante 20 minutos en la zona lumbar acompañado de la compresa caliente. En seguida se le aplico US a un 1Hz por 7 min. al 20%. Después realizamos masaje relajante en la zona afectada por 10 minutos. Después realizamos ejercicios de fortalecimiento muscular isométricos a cor abdominal y glúteos durante 5 minutos. También realizamos estiramientos paravertebrales lumbares y erectores de columna dando énfasis en el lado derecho. Por ultimo realizamos el ejercicio de gato camello ya que este ejercicio esta destinado para la zona lumbar, con la finalidad de dar mayor flexibilidad, movilidad y fuerza. También realizamos los ejercicios de William que nos ayudaran en la zona lumbar para fortalecimiento de abdominales y estiramiento de la fascia lumbar, cada ejercicio lo realizamos 3 series de 10. El primer ejercicio el paciente se pone en posición de decúbito supino con las caderas y rodillas flexionadas con los pies sobre la camilla, se le pide que presione la zona lumbar sobre la camilla. El segundo ejercicio igual la misma posición decúbito supino pero ahora se le pide que leve una rodilla hacia el pecho y que mantenga y después relaje y lo realice con la otra pierna alternando. El tercer ejercicio igual la misma posición de decúbito supino pero ahora se le pide que lleve las 2 rodillas al pecho sosteniéndolas con sus manos unos segundos y después soltarlas.','physiotherapy_classic_actividades',NULL,314,'2022-09-20 17:32:34','2022-09-20 17:32:34',NULL,41),(32107,'Observaciones',NULL,'El paciente presenta dolor en la zona lumbar.','physiotherapy_classic_observaciones',NULL,314,'2022-09-20 17:32:34','2022-09-20 17:32:34',NULL,41),(32108,'Fisioterapeuta',NULL,'Lic. Antonio Mendoza','physiotherapy_classic_fisioterapeuta',NULL,314,'2022-09-20 17:32:34','2022-09-20 17:32:34',NULL,41),(32109,'Objetivo',NULL,'Eliminar inflamación y disminuir dolor','physiotherapy_classic_objective',NULL,334,'2022-09-20 19:23:34','2022-09-20 19:23:34',NULL,14),(32110,'Numero de sesión',NULL,'1','physiotherapy_classic_numero_de_sesion',NULL,334,'2022-09-20 19:23:34','2022-09-20 19:23:34',NULL,14),(32111,'Actividades',NULL,'Interferenciales 2500 hz latido alto y bajo de 1-10hz ciclo 10/10 20 minu