(57805,'Actividades',NULL,'TENS asimétrico 50 Hz con compresa eléctrica en zona lumbar por 15 minutos, corrientes rusas en glúteos y cuádriceps 7 minutos cada zona subida 4 bajada 2, movilización activa de 4 extremidades, estiramientos gentiles a isquiotibiales, tríceps sural, erectores de columna, ejercicios para equilibrio en 1 y 2 puntos.','physiotherapy_classic_actividades',NULL,347,'2023-01-10 15:04:18','2023-01-10 15:04:18',NULL,54),(57806,'Observaciones',NULL,'Paciente refiere sentirse bien, sin ninguna molestia.','physiotherapy_classic_observaciones',NULL,347,'2023-01-10 15:04:18','2023-01-10 15:04:18',NULL,54),(57807,'Fisioterapeuta',NULL,'LTF Marisela Alegría Ruiz','physiotherapy_classic_fisioterapeuta',NULL,347,'2023-01-10 15:04:18','2023-01-10 15:04:18',NULL,54),(57808,'Motivo de consulta',NULL,'{\"data\":\"Dolor a la mitad del pie y lateral. le dio unos dias antes de navidad. ayer jugando futbol no ha dolido. Crosfit estaba haciendo paro a inicios de diciembre de repende le dio\"}','cause_of_appoinment',NULL,469,'2023-01-10 17:01:08','2023-01-10 17:01:08',NULL,3),(57809,'Características',NULL,'{\"data\":null}','pain',NULL,469,'2023-01-10 17:01:08','2023-01-10 17:01:08',NULL,3),(57810,'Irradiación',NULL,'{\"data\":null}','pain',NULL,469,'2023-01-10 17:01:08','2023-01-10 17:01:08',NULL,3),(57811,'EVA',NULL,'6','valoration_pain',NULL,469,'2023-01-10 17:01:08','2023-01-10 17:01:08',NULL,3),(57812,'Tiempo de Evolución',NULL,'{\"data\":\"Unos dias antes de navidad, solo alpisar\"}','evolution',NULL,469,'2023-01-10 17:01:08','2023-01-10 17:01:08',NULL,3),(57813,'Frecuencia Cardiaca',NULL,'{\"data\":\"Negado\"}','vital_signs',NULL,469,'2023-01-10 17:01:08','2023-01-10 17:01:08',NULL,3),(57814,'Frecuencia Respiratoria',NULL,'{\"data\":\"Negado\"}','vital_signs',NULL,469,'2023-01-10 17:01:08','2023-01-10 17:01:08',NULL,3),(57815,'Presión Arterial (Sistólica/Diastólica)',NULL,'{\"data\":\"Negado\"}','vital_signs',NULL,469,'2023-01-10 17:01:08','2023-01-10 17:01:08